// webapp/app.js - Interactive Controller with Full 500-Point Master Dataset

function switchTab(tabId) {
    document.querySelectorAll('.tab-content').forEach(el => {
        el.classList.add('hidden');
        el.classList.remove('block');
    });

    document.querySelectorAll('.nav-btn').forEach(btn => {
        btn.classList.remove('bg-gold-500/20', 'text-gold-400', 'border', 'border-gold-500/30');
        btn.classList.add('text-slate-400');
    });

    const activeTab = document.getElementById('tab-' + tabId);
    if (activeTab) {
        activeTab.classList.remove('hidden');
        activeTab.classList.add('block');
    }

    const activeBtn = document.getElementById('btn-' + tabId);
    if (activeBtn) {
        activeBtn.classList.add('bg-gold-500/20', 'text-gold-400', 'border', 'border-gold-500/30');
        activeBtn.classList.remove('text-slate-400');
    }
}

