function render160Points() {
    const container = document.getElementById('points-container');
    if (!container) return;

    let html = '';
    DOMAINS_DATA.forEach(domain => {
        html += `
            <div class="glass-card rounded-2xl p-6 space-y-4 mb-6">
                <div class="flex items-center gap-3 border-b border-gold-500/20 pb-3">
                    <span class="text-2xl">${domain.icon}</span>
                    <div>
                        <h3 class="text-lg md:text-xl font-bold text-gold-400 font-cinzel">${domain.title}</h3>
                        <p class="text-xs text-amber-300/70 font-hindi mt-0.5">ज्योतिषीय आधार: ${domain.astroBasis}</p>
                    </div>
                </div>
                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
        `;

        domain.points.forEach(p => {
            html += `
                <div class="point-card p-4 rounded-xl bg-cosmic-800/60 border border-slate-700/50 hover:border-gold-500/40 transition-all">
                    <div class="flex items-start gap-3">
                        <span class="w-7 h-7 rounded-full bg-gold-500/20 text-gold-400 text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">${p.num}</span>
                        <div>
                            <h4 class="text-sm font-bold text-white">${p.title}</h4>
                            <p class="text-xs text-slate-300 mt-1.5 font-hindi leading-relaxed">${p.desc}</p>
                        </div>
                    </div>
                </div>
            `;
        });

        html += `
                </div>
            </div>
        `;
    });

    container.innerHTML = html;
}

function filter160Points() {
    const query = document.getElementById('search160').value.toLowerCase().trim();
    const cards = document.querySelectorAll('.point-card');
    let visibleCount = 0;
    cards.forEach(card => {
        const text = card.textContent.toLowerCase();
        if (text.includes(query)) {
            card.style.display = 'block';
            visibleCount++;
        } else {
            card.style.display = 'none';
        }
    });
    
    const countDisplay = document.getElementById('search-count');
    if (countDisplay) {
        if (query) {
            countDisplay.innerText = `मिलते-जुलते परिणाम: ${visibleCount} / 500`;
            countDisplay.classList.remove('hidden');
        } else {
            countDisplay.classList.add('hidden');
        }
    }
}

// Initialize on page load
document.addEventListener('DOMContentLoaded', () => {
    render160Points();
});
